def test_cache_directory_logic_parity():
    from platformdirs import user_cache_dir
    # Verify that the function call does not raise errors in the current environment
    try:
        path = user_cache_dir('LinkWatch')
        assert 'LinkWatch' in path
    except Exception as e:
        pytest.fail(f'user_cache_dir raised an exception: {e}')

def test_pydantic_v2_model_dump_compatibility():
    from pydantic import BaseModel
    class TestModel(BaseModel):
        id: int
        name: str
    m = TestModel(id=1, name='test')
    # Verify the new model_dump method works as expected
    assert m.model_dump() == {'id': 1, 'name': 'test'}

def test_pydantic_v2_validation_logic():
    from pydantic import BaseModel, ValidationError
    class TestModel(BaseModel):
        val: int
    with pytest.raises(ValidationError):
        TestModel(val='not_an_int')
